={{ (() => {
  const body = $json.body || {};
  const errores = [];
  const ESQUEMA = {
    type: 'object',
    required: ['nombre', 'telefono', 'mensaje'],
    properties: {
      nombre: { type: 'string', minLength: 2, maxLength: 100, description: 'Nombre de quien escribe' },
      telefono: { type: 'string', pattern: '8 a 15 dígitos (se aceptan espacios, guiones, paréntesis y +)', description: 'Teléfono o WhatsApp' },
      mensaje: { type: 'string', minLength: 1, maxLength: 1000, description: 'Consulta o mensaje' }
    }
  };
  let nombre = null, telefono = null, mensaje = null;
  if (!('nombre' in body) || body.nombre === null || body.nombre === '') errores.push({ p: 'nombre', m: 'Falta el campo obligatorio "nombre"' });
  else if (typeof body.nombre !== 'string') errores.push({ p: 'nombre', m: 'Tiene que ser texto' });
  else { nombre = body.nombre.trim().replace(/\s+/g, ' '); if (nombre.length < 2 || nombre.length > 100) errores.push({ p: 'nombre', m: 'Tiene que tener entre 2 y 100 caracteres' }); }
  if (!('telefono' in body) || body.telefono === null || body.telefono === '') errores.push({ p: 'telefono', m: 'Falta el campo obligatorio "telefono"' });
  else if (typeof body.telefono !== 'string' && typeof body.telefono !== 'number') errores.push({ p: 'telefono', m: 'Tiene que ser texto o número' });
  else {
    const crudo = String(body.telefono).trim();
    telefono = crudo.replace(/\D/g, '');
    if (!/^[+\d\s().-]+$/.test(crudo)) errores.push({ p: 'telefono', m: 'Solo puede tener números, espacios, guiones, paréntesis y +' });
    else if (telefono.length < 8 || telefono.length > 15) errores.push({ p: 'telefono', m: 'Tiene que tener entre 8 y 15 dígitos' });
  }
  if (!('mensaje' in body) || body.mensaje === null) errores.push({ p: 'mensaje', m: 'Falta el campo obligatorio "mensaje"' });
  else if (typeof body.mensaje !== 'string') errores.push({ p: 'mensaje', m: 'Tiene que ser texto' });
  else { mensaje = body.mensaje.trim(); if (mensaje.length < 1 || mensaje.length > 1000) errores.push({ p: 'mensaje', m: 'Tiene que tener entre 1 y 1000 caracteres' }); }
  if (errores.length === 0) return { valid: true, validationError: null, datos: { nombre, telefono, mensaje } };
  const detalles = {};
  errores.forEach(e => { if (!(e.p in detalles)) detalles[e.p] = e.m; });
  return {
    valid: false,
    validationError: 'Datos inválidos (' + errores.length + ' problema' + (errores.length > 1 ? 's' : '') + '): ' + errores.map(e => e.p + ': ' + e.m).join('; '),
    details: detalles,
    requiredSchema: ESQUEMA
  };
})() }}

